const result = JSON.parse($json.stdout ?? "{}");
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
const errorPage = message => `<!doctype html><html lang="hu"><head><meta charset="utf-8"><title>Hiba – YouTube meta</title><style>body{font:16px system-ui;max-width:650px;margin:48px auto;padding:0 20px;color:#222}.error{border-left:4px solid #b00020;padding:12px 16px;background:#fff4f4;white-space:pre-wrap}</style></head><body><h1>Nem sikerült megnyitni az űrlapot</h1><p class="error">${esc(message)}</p><p>Javítsd a jelzett hibát, majd töltsd újra az oldalt. Ha a hiba megmarad, küldd el ezt az üzenetet az üzemeltetőnek.</p></body></html>`;
if (!result.ok) return [{json:{html:errorPage(result.error?.message ?? "Ismeretlen hiba történt az űrlap adatainak betöltésekor.")}}];
if (!Array.isArray(result.channels) || !Array.isArray(result.folders)) throw new Error("Az űrlap adatainak formátuma hibás: channels és folders listát vártam.");
const {channels, folders} = result;
const webhookUrl = $('Űrlap megnyitása').first().json.webhookUrl;
if (!webhookUrl) throw new Error("Nem érkezett meg a webhook URL-je; az űrlap beküldési címe nem állítható össze.");
const action = webhookUrl.replace(/youtube-meta$/, 'youtube-meta-submit');
const channelOptions = channels.map(c => `<option value="${esc(c.key)}">${esc(c.displayName)}</option>`).join('');
const folderOptions = folders.map(name => `<option value="${esc(name)}">${esc(name)}</option>`).join('');
const html = `<!doctype html>
<html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>YouTube meta</title>
<style>body{font:16px system-ui;max-width:560px;margin:48px auto;padding:0 20px}select{display:block;width:100%;padding:12px;margin:8px 0 20px}button{padding:12px 24px}</style></head>
<body><h1>YouTube meta</h1>
<form method="post" action="${esc(action)}">
<label for="channelKey">Csatorna</label><select id="channelKey" name="channelKey" required><option value="">Válassz csatornát</option>${channelOptions}</select>
<label for="videoFolder">Videómappa</label><select id="videoFolder" name="videoFolder" required><option value="">Válassz mappát</option>${folderOptions}</select>
<button id="next" type="submit" disabled>Tovább</button></form>
<script>const c=document.querySelector('#channelKey'),f=document.querySelector('#videoFolder'),b=document.querySelector('#next');function update(){b.disabled=!(c.value&&f.value)}c.addEventListener('change',update);f.addEventListener('change',update);update();</script>
</body></html>`;
return [{json:{html}}];

const body = $json.body ?? {};
const channelKey = typeof body.channelKey === "string" ? body.channelKey.trim() : "";
const videoFolder = typeof body.videoFolder === "string" ? body.videoFolder.trim() : "";
const problems = [];
if (!channelKey) problems.push("Nem érkezett csatornaválasztás.");
if (!videoFolder) problems.push("Nem érkezett videómappa-választás.");
if (videoFolder === "." || videoFolder === ".." || videoFolder.includes("/") || videoFolder.includes("\\")) problems.push("A videómappa neve érvénytelen; csak egy közvetlen mappanév adható meg.");
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
if (problems.length) {
  const message = problems.join(" ");
  const html = `<!doctype html><html lang="hu"><meta charset="utf-8"><title>Hiba a beküldésnél</title><body><h1>Nem sikerült rögzíteni a választást</h1><p>${esc(message)}</p><p>Menj vissza az űrlapra, javítsd a választást, majd küldd be újra.</p></body></html>`;
  return [{json:{ok:false,error:{stage:"űrlap beküldésének ellenőrzése",message},html}}];
}
const sessionId = `${channelKey}:${videoFolder}`;
const webhookUrl = String($('Kiválasztás fogadása').first().json.webhookUrl ?? '');
const origin = webhookUrl.split('/webhook/')[0];
if (!origin) throw new Error('Nem állítható össze a chat webcíme.');
const chatUrl = `${origin}/webhook/c50219e8-5cba-4cf9-a77f-9c5908890b4f/chat#sessionId=${encodeURIComponent(sessionId)}`;
const message = `A chat indul: ${channelKey} csatorna, ${videoFolder} videómappa.`;
const html = `<!doctype html><html lang="hu"><meta charset="utf-8"><title>YouTube metaadat-chat</title><body><h1>Indul a metaadat-chat</h1><p>${esc(message)}</p><p><a href="${esc(chatUrl)}">Ha nem nyílik meg automatikusan, kattints ide.</a></p><script>window.location.replace(${JSON.stringify(chatUrl)});</script></body></html>`;
return [{json:{ok:true,channelKey,videoFolder,sessionId,chatUrl,message,html}}];
